/* ============ KONSTAN ============ */
const STORAGE_KEY='saturnvss_invoice_maker_v1';
const BRAND_NAME='Saturnvss';
const BRAND_SUB='Fashion & Beauty Enthusiast';
// Rekening pembayaran permanen — selalu dipakai di setiap invoice
const BANK_NAME='BNI';
const ACCOUNT_NAME='Dwi Lestari';
const ACCOUNT_NUMBER='1791906505';
const SIGNATURE_IMG_B64='data:image/png;base64,';

/* ============ STATE ============ */
let state=null;
let tab='create'; // 'create' | 'history'
let draftItems=[{service:'',qty:1,rate:0}];

function load(){
  try{
    const raw=localStorage.getItem(STORAGE_KEY);
    state=raw?JSON.parse(raw):{seq:{},history:[]};
  }catch(e){ state={seq:{},history:[]}; }
  if(!state.seq)state.seq={};
  if(!state.history)state.history=[];
}
function save(){ localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }

/* ============ UTIL ============ */
function uid(){return 'id'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);}
function rp(n){ n=Number(n)||0; return 'Rp'+n.toLocaleString('id-ID');}
function fmtDate(s){ if(!s)return '-'; const d=new Date(s+'T00:00:00'); if(isNaN(d))return s; return d.toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}); }
function fmtDateShort(s){ if(!s)return '-'; const d=new Date(s+'T00:00:00'); if(isNaN(d))return s; return d.toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}); }
function todayISO(){return new Date().toISOString().slice(0,10);}
function esc(s){ return (s==null?'':String(s)).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function toast(msg){
  const t=document.getElementById('toast'); t.textContent=msg; t.classList.add('show');
  clearTimeout(window._toastTimer); window._toastTimer=setTimeout(()=>t.classList.remove('show'),2200);
}
function icons(){ if(window.lucide) lucide.createIcons(); }
function invoiceTotal(items){ return items.reduce((s,it)=>s+Number(it.qty||0)*Number(it.rate||0),0); }
function nextInvoiceNumber(){
  const now=new Date(); const key=`${now.getFullYear()}${String(now.getMonth()+1).padStart(2,'0')}`;
  const seq=(state.seq[key]||0)+1;
  return {number:`INV-DWL-${key}-${String(seq).padStart(3,'0')}`,key};
}

/* ============ RENDER ============ */
function render(){
  const app=document.getElementById('app');
  app.innerHTML=`
    <svg class="lily-watermark" viewBox="0 0 200 200" fill="none"><path d="M100 20 C 60 40, 60 100, 100 180 C140 100, 140 40, 100 20 Z" fill="currentColor"/><path d="M20 100 C 40 60, 100 60, 180 100 C100 140, 40 140, 20 100 Z" fill="currentColor" opacity=".6"/></svg>
    <div class="shell">
      <div class="topbar">
        <div class="flower">🌸</div>
        <div><h1>${BRAND_NAME} Invoice</h1><p>${esc(BRAND_SUB)}</p></div>
      </div>
      <div class="tabs">
        <button class="tab-btn ${tab==='create'?'active':''}" data-tab="create"><i data-lucide="file-plus-2"></i>Buat Invoice</button>
        <button class="tab-btn ${tab==='history'?'active':''}" data-tab="history"><i data-lucide="history"></i>Riwayat</button>
      </div>
      ${tab==='create'?viewCreate():viewHistory()}
    </div>
  `;
  icons();
}

function viewCreate(){
  const total=invoiceTotal(draftItems);
  return `
  <div class="card">
    <div class="section-label">Kepada</div>
    <div class="field"><label>Nama Brand</label><input id="f-brand" placeholder="Nama brand" value="${esc(window._formBrand||'')}"></div>
    <div class="field"><label>Contact Person (opsional)</label><input id="f-pic" placeholder="Nama PIC" value="${esc(window._formPic||'')}"></div>

    <div class="section-label">Tanggal</div>
    <div class="field"><input type="date" id="f-date" value="${window._formDate||todayISO()}"></div>

    <div class="section-label">Item</div>
    <div id="items-wrap">
      ${draftItems.map((it,idx)=>itemRow(it,idx)).join('')}
    </div>
    <button class="btn btn-ghost btn-sm" data-action="add-item"><i data-lucide="plus"></i>Tambah Item</button>

    <div class="grand-total"><span class="lbl">Total</span><span class="amt">${rp(total)}</span></div>

    <div class="section-label">Catatan Pembayaran (opsional)</div>
    <div class="field"><textarea id="f-notes" placeholder="Kosongkan jika tidak perlu...">${esc(window._formNotes||'')}</textarea></div>

    <button class="btn btn-primary btn-block" data-action="quick-save"><i data-lucide="image-down"></i>Simpan &amp; Unduh Gambar</button>
  </div>
  `;
}
function itemRow(it,idx){
  const lineTotal=Number(it.qty||0)*Number(it.rate||0);
  return `<div class="item-row" data-item-idx="${idx}">
    <div class="field"><label>Keterangan</label><input class="it-service" value="${esc(it.service)}" placeholder="TikTok Video"></div>
    <div class="field"><label>Jml</label><input type="number" class="it-qty" value="${it.qty}" min="1"></div>
    <div class="field"><label>Harga</label><input type="number" class="it-rate" value="${it.rate}"></div>
    <button class="rm" data-action="remove-item" data-idx="${idx}"><i data-lucide="x"></i></button>
  </div>`;
}

function viewHistory(){
  const list=[...state.history].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));
  if(list.length===0){
    return `<div class="card"><div class="empty-state">
      <i data-lucide="history"></i>
      <div class="t1">Belum ada riwayat</div>
      <div class="t2">Invoice yang kamu buat akan otomatis muncul di sini.</div>
    </div></div>`;
  }
  return `<div class="history-list">
    ${list.map(inv=>`<div class="card hist-card">
      <div class="row1">
        <div><div class="brand">${esc(inv.brandName)}</div><div class="date">${fmtDateShort(inv.invoiceDate)}</div></div>
        <div class="amt">${rp(invoiceTotal(inv.items))}</div>
      </div>
      <div class="actions">
        <button class="btn btn-ghost btn-sm" data-action="redownload" data-id="${inv.id}"><i data-lucide="image-down"></i>Unduh Ulang</button>
        <button class="btn btn-danger btn-sm" data-action="delete-invoice" data-id="${inv.id}"><i data-lucide="trash-2"></i></button>
      </div>
    </div>`).join('')}
  </div>`;
}

/* ============ INVOICE IMAGE ============ */
function invoicePaperHTML(inv){
  const total=invoiceTotal(inv.items);
  return `
  <div class="invoice-paper">
    <div class="inv-header">
      <svg class="lily" width="90" height="90" viewBox="0 0 100 100"><path d="M50 10 C 30 20, 30 50, 50 90 C70 50, 70 20, 50 10 Z" fill="currentColor"/></svg>
      <div style="display:flex; justify-content:space-between; align-items:flex-start;">
        <div><div class="brandname">${esc(BRAND_NAME.toUpperCase())}</div><div class="brandsub">${esc(BRAND_SUB)}</div></div>
        <div class="inv-title">INVOICE</div>
      </div>
    </div>
    <div class="inv-body">
      <div class="inv-meta">
        <div class="block"><div class="lbl">Bill To</div><div class="val"><strong>${esc(inv.brandName||'-')}</strong>${inv.pic?`<br>${esc(inv.pic)}`:''}</div></div>
        <div class="block" style="text-align:right;">
          <div class="lbl">Date</div><div class="val">${fmtDate(inv.invoiceDate)}</div>
        </div>
      </div>
      <table class="inv-table">
        <thead><tr><th>Service</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead>
        <tbody>${inv.items.map(it=>`<tr><td>${esc(it.service||'-')}</td><td>${it.qty}</td><td>${rp(it.rate)}</td><td>${rp(it.qty*it.rate)}</td></tr>`).join('')}</tbody>
      </table>
      <div class="inv-totals">
        <div class="row total"><span>Total</span><span>${rp(total)}</span></div>
      </div>
      <div class="inv-pay">
        <div class="lbl">Payment Information</div>
        <div style="font-size:17px; line-height:1.8;"><strong>${esc(BANK_NAME)}</strong><br>${esc(ACCOUNT_NAME)} — ${esc(ACCOUNT_NUMBER)}</div>
        ${inv.paymentNotes?`<div style="font-size:14.5px; color:#9a828c; margin-top:8px;">${esc(inv.paymentNotes)}</div>`:''}
      </div>
      <div class="inv-signature">
        <img src="${SIGNATURE_IMG_B64}" alt="Signature">
        <div class="sig-name">Dwi Lestari</div>
      </div>
    </div>
    <div class="inv-footer">Thank you</div>
  </div>`;
}
async function generateAndDownloadImage(inv){
  if(!window.html2canvas){ toast('Gagal memuat komponen gambar'); return; }
  toast('Menyiapkan gambar...');
  const holder=document.createElement('div');
  holder.style.position='fixed'; holder.style.left='-9999px'; holder.style.top='0';
  holder.innerHTML=invoicePaperHTML(inv);
  document.body.appendChild(holder);
  try{
    // beri jeda singkat agar font selesai dimuat sebelum di-screenshot
    if(document.fonts && document.fonts.ready) await document.fonts.ready;
    await new Promise(r=>setTimeout(r,80));
    // Kartu invoice sudah didesain rasio 3:4 (810x1080) sehingga hasil capture otomatis penuh mengisi
    // bingkai 3:4 tanpa perlu bingkai/margin tambahan — cukup skalakan ke resolusi output yang nyaman dibaca.
    const targetWidth=1080;
    const scale=targetWidth/810;
    const canvas=await html2canvas(holder.firstElementChild,{scale,backgroundColor:'#ffffff'});

    const dataUrl=canvas.toDataURL('image/jpeg',0.92);
    const a=document.createElement('a');
    a.href=dataUrl; a.download=`${inv.number||'invoice'}.jpg`;
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    toast('Gambar invoice diunduh 🌸');
  }catch(err){
    console.error(err);
    toast('Gagal membuat gambar, coba lagi');
  }finally{
    document.body.removeChild(holder);
  }
}

/* ============ ACTIONS ============ */
function syncFormToMemory(){
  window._formBrand=document.getElementById('f-brand')?.value||'';
  window._formPic=document.getElementById('f-pic')?.value||'';
  window._formDate=document.getElementById('f-date')?.value||todayISO();
  window._formNotes=document.getElementById('f-notes')?.value||'';
  const rows=document.querySelectorAll('#items-wrap [data-item-idx]');
  draftItems=Array.from(rows).map(r=>({
    service:r.querySelector('.it-service').value,
    qty:Number(r.querySelector('.it-qty').value)||0,
    rate:Number(r.querySelector('.it-rate').value)||0
  }));
}
function resetForm(){
  window._formBrand=''; window._formPic=''; window._formDate=todayISO(); window._formNotes='';
  draftItems=[{service:'',qty:1,rate:0}];
}
async function quickSave(){
  syncFormToMemory();
  const brand=window._formBrand.trim();
  if(!brand){ toast('Nama brand wajib diisi'); return; }
  const items=draftItems.filter(it=>it.service.trim()!=='' || it.qty>0);
  const finalItems=items.length?items:draftItems;
  const {number,key}=nextInvoiceNumber();
  const inv={
    id:uid(), number, brandName:brand, pic:window._formPic.trim(),
    invoiceDate:window._formDate||todayISO(), items:finalItems,
    paymentNotes:window._formNotes.trim(), createdAt:new Date().toISOString()
  };
  state.seq[key]=(state.seq[key]||0)+1;
  state.history.push(inv);
  save();
  await generateAndDownloadImage(inv);
  resetForm();
  tab='history';
  render();
}
async function redownload(id){
  const inv=state.history.find(x=>x.id===id);
  if(!inv)return;
  await generateAndDownloadImage(inv);
}
function confirmDelete(id){
  const overlay=document.getElementById('overlay');
  let m=document.getElementById('confirm-modal');
  if(!m){ m=document.createElement('div'); m.id='confirm-modal'; m.className='modal'; document.body.appendChild(m); }
  m.innerHTML=`
    <h3>Hapus Invoice</h3>
    <p>Riwayat invoice ini akan dihapus permanen dari perangkat ini. Lanjutkan?</p>
    <div class="row">
      <button class="btn btn-ghost" data-action="close-confirm">Batal</button>
      <button class="btn btn-danger" data-action="do-delete" data-id="${id}">Hapus</button>
    </div>`;
  overlay.classList.add('show'); m.classList.add('show');
}
function closeConfirm(){
  document.getElementById('overlay').classList.remove('show');
  const m=document.getElementById('confirm-modal'); if(m)m.classList.remove('show');
}
function deleteInvoice(id){
  state.history=state.history.filter(x=>x.id!==id);
  save(); closeConfirm(); toast('Invoice dihapus'); render();
}

/* ============ EVENTS ============ */
document.addEventListener('click',e=>{
  const overlay=document.getElementById('overlay');
  if(e.target===overlay){ closeConfirm(); return; }
  const t=e.target.closest('[data-tab]');
  if(t){ syncFormToMemory(); tab=t.dataset.tab; render(); return; }
  const a=e.target.closest('[data-action]');
  if(!a)return;
  const act=a.dataset.action; const id=a.dataset.id;
  if(act==='add-item'){ syncFormToMemory(); draftItems.push({service:'',qty:1,rate:0}); render(); }
  else if(act==='remove-item'){ syncFormToMemory(); draftItems.splice(Number(a.dataset.idx),1); if(draftItems.length===0)draftItems.push({service:'',qty:1,rate:0}); render(); }
  else if(act==='quick-save'){ quickSave(); }
  else if(act==='redownload'){ redownload(id); }
  else if(act==='delete-invoice'){ confirmDelete(id); }
  else if(act==='close-confirm'){ closeConfirm(); }
  else if(act==='do-delete'){ deleteInvoice(id); }
});
document.addEventListener('input',e=>{
  if(e.target.matches('.it-qty, .it-rate')){
    // update baris total kecil tanpa full re-render biar tidak kehilangan fokus input
  }
});

/* ============ INIT ============ */
load();
resetForm();
render();
